212:     public readonly duration: number
213:   ) {
214:     super(taskId);
215:   }
216: }
217: 
218: // Event handlers
219: @EventHandler(TaskCompletedEvent)
220: export class TaskCompletedHandler {
221:   constructor(
222:     private metricsRepository: IMetricsRepository,
223:     private sessionService: SessionLifecycleService
224:   ) {}
225: 
226:   async handle(event: TaskCompletedEvent): Promise<void> {
