260: ### Application Layer (Use Cases)
261: ```typescript
262: // core$application$use-cases/
263: export class AssignTaskUseCase {
264:   constructor(
265:     private taskRepository: ITaskRepository,
266:     private agentRepository: IAgentRepository,
267:     private eventBus: DomainEventBus
268:   ) {}
269: 
270:   async execute(command: AssignTaskCommand): Promise<TaskResult> {
271:     // 1. Validate command
272:     await this.validateCommand(command);
273: 
274:     // 2. Load aggregates
275:     const task = await this.taskRepository.findById(command.taskId);
276:     const agent = await this.agentRepository.findById(command.agentId);
277: 
278:     // 3. Business logic (in domain)
279:     task.assignTo(agent);
280: 
281:     // 4. Persist changes
282:     await this.taskRepository.save(task);
283: 
284:     // 5. Publish domain events
285:     task.getUncommittedEvents().forEach(event =>
286:       this.eventBus.publish(event)
287:     );
288: 
289:     // 6. Return result
290:     return TaskResult.success(task);
291:   }
292: }
293: ```
